/* Maxxicharge-Karte im Stil der Maxxisun-App: Haus mit PV und Speicher, Kacheln, Verlauf „Haushalt“.
 * Eine Datei, keine Abhängigkeiten. Dashboard: type: custom:maxxicharge-card
 *
 * Optionen (alle optional):
 *   device: <Geräte-ID>       # CCU oder „Maxxicharge Gesamt“ (ohne Angabe: Gesamtübersicht); im Editor auswählbar
 *   switcher: true            # Umschalter Gesamt / CCUs in der Karte (Standard: an, wenn kein Gerät festgelegt ist)
 *   modules: [scene, tiles, chart, stats]   # Bausteine: Haus-Grafik, Kacheln, Verlauf, Kennzahlen
 *   tiles: [pv, house, grid, ccu, store]    # welche Kacheln
 *   title: Maxxicharge        # Überschrift
 *   hours: 3                  # Zeitraum des Verlaufs in Stunden
 *   pv_max: 4000              # Skala des PV-Balkens in W
 *   house_max: 3000           # Skala des Verbrauchs-Balkens in W
 *   ccu_max: 2300             # Skala des CCU-Balkens in W
 *   entities: { pv: sensor.xxx, grid: sensor.xxx }   # Entities überschreiben (Schlüssel siehe KEYS)
 * Die Entities werden automatisch gefunden (Gesamtübersicht oder gewählte CCU).
 */
(() => {
  const TOTAL_KEYS = {
    pv: "total_pv_power",
    charge: "total_battery_charge_power",
    discharge: "total_battery_discharge_power",
    grid: "total_grid_power",
    house: "total_house_power",
    soc: "total_soc",
    feed: "total_ac_feed",
    draw: "total_ac_draw",
    runtime: "total_runtime",
    ttf: "total_time_to_full",
    autarky: "total_autarky",
    usable: "total_usable_energy",
    pvtoday: "total_pv_today",
    temp: "total_temperature",
    fault: "total_fault",
    lock: "write_lock",
    online: "total_online",
  };
  // Entities einer einzelnen CCU (Übersetzungsschlüssel der Integration)
  const CCU_KEYS = {
    pv: "pv_power",
    charge: "battery_charge_power",
    discharge: "battery_discharge_power",
    grid: "grid_power",
    soc: "soc",
    feed: "ac_feed_power",
    draw: "ac_draw_power",
    runtime: "runtime",
    ttf: "time_to_full",
    usable: "usable_energy_kwh",
    pvtoday: "pv_energy_today",
    temp: "temperature",
    online: "online",
    f1: "inverter_fault",
    f2: "battery_fault",
    f3: "meter_timeout",
  };
  const ALL_MODULES = ["scene", "tiles", "chart", "stats"];
  const ALL_TILES = ["pv", "house", "grid", "ccu", "store"];
  const C = { grid: "#e0568a", ccu: "#a98bf0", draw: "#f5a623", pv: "#f5a623", green: "#3ecf5a", blue: "#4a90e2" };

  const fmtW = (v) => {
    if (v === null || v === undefined || Number.isNaN(v)) return "–";
    return Math.abs(v) >= 10000 ? `${(v / 1000).toFixed(1).replace(".", ",")} kW` : `${Math.round(v)} W`;
  };
  const fmtH = (h) => {
    if (h === null || h === undefined || Number.isNaN(h)) return "–";
    if (h < 1) return `${Math.round(h * 60)} min`;
    return `${Math.floor(h)} h ${Math.round((h % 1) * 60)} min`;
  };
  const pct = (v, max) => (v === null || !max ? 0 : Math.max(0, Math.min(100, (v / max) * 100)));

  function niceRange(values) {
    // vier gleich große Schritte mit runden Werten, Null liegt auf einer Linie
    const min = Math.min(0, ...values), max = Math.max(0, ...values);
    for (const step of [25, 50, 100, 200, 250, 500, 1000, 2000, 5000]) {
      const lo = Math.floor(min / step) * step;
      const hi = lo + 4 * step;
      if (hi >= max && hi - lo >= 100) return { lo, hi, step };
    }
    return { lo: 0, hi: 10000, step: 2500 };
  }

  // ---------- Szene: Haus mit beliebig vielen CCUs und Speichern ----------
  // Bilder: Haus (Render von maxxisun.de, Würfel und Teil der Leitungen entfernt) sowie 3D-Modelle von Speicher (M5.0) und CCU V2+,
  // die nach den Herstellermaßen modelliert und in der Perspektive des Hauses gerendert wurden.
  // Alle Maße in Bildkoordinaten (1000 x 731); die Szene wird mit SCENE_K auf die viewBox (400 breit) skaliert.
  const SCENE_IMG = {
    house: "data:image/webp;base64,",
    battery: "data:image/webp;base64,",
    ccu: "data:image/webp;base64,",
  };
  const SCENE_K = 0.4;
  const SCENE = {
    meter: [283, 590],
    gridWire: [[283, 590], [300, 607], [520, 538], [548, 550], [566, 546]],  // Zähler bis zum Gerätefeld
    roofIn: [536, 352],              // Solarleitung beginnt am Dachrand
    houseIn: [801, 345],             // Leitung ins Haus (unter dem Fenster)
    wallBase: (x) => 457 + 0.37 * (792 - x),  // Linie, an der die Wand auf den Boden trifft
    battery: { foot: [618, 538], step: [78, -22], span: [156, -44], max: 6, w: 74.0, h: 102.2, fx: 37.0, fy: 82.0 },
    ccu: { foot: [664, 563], step: [78, -22], span: [156, -44], max: 4, w: 74.0, h: 54.3, fx: 37.0, fy: 34.7 },
    lift: 61.9,   // Höhe der Speicher-Oberseite über der Mitte der Standfläche (aus dem CAD)
    perTower: 3,  // Speicher je Turm, danach steht der nächste Turm daneben
    ccuH: 20,     // Bauhöhe einer CCU beim Stapeln
  };

  // Ordnet n Geräte in einer Reihe an; ab vier Geräten rücken sie zusammen und werden kleiner.
  function sceneRow(n, cfg) {
    const shown = Math.min(Math.max(n, 0), cfg.max), items = [];
    let st = cfg.step, scale = 1;
    if (shown > 3) {
      st = [cfg.span[0] / (shown - 1), cfg.span[1] / (shown - 1)];
      scale = Math.max(0.55, Math.min(1, (st[0] / cfg.step[0]) * 1.15));
    }
    for (let i = 0; i < shown; i++) items.push({ x: cfg.foot[0] + st[0] * i, y: cfg.foot[1] + st[1] * i, s: scale });
    return { items, more: Math.max(0, n - shown) };
  }

  // Gesamtlayout: Speicher stapeln sich zu Türmen (bis SCENE.perTower übereinander), weitere Türme stehen daneben.
  // Die CCU sitzt oben auf dem Turm; weitere CCUs stapeln sich darüber.
  function sceneLayout(nCcu, nBat) {
    const per = SCENE.perTower, nTow = Math.ceil(Math.max(nBat, 0) / per);
    const row = sceneRow(nTow, SCENE.battery), items = [], cnt = [];
    row.items.forEach((t, j) => {
      const c = Math.min(per, nBat - j * per);
      cnt.push(c);
      for (let l = 0; l < c; l++) items.push({ x: t.x, y: t.y - l * SCENE.lift * t.s, s: t.s, j, l });
    });
    const bat = { items, more: Math.max(0, nBat - items.length) };
    let ccu;
    if (row.items.length) {
      const nt = row.items.length, total = Math.max(nCcu, 0), shown = Math.min(total, nt + 2), cs = [];
      for (let i = 0; i < shown; i++) {
        const j = Math.min(i, nt - 1), t = row.items[j], lvl = i - j;
        cs.push({ x: t.x, y: t.y - (cnt[j] * SCENE.lift + lvl * SCENE.ccuH) * t.s, s: t.s, j });
      }
      ccu = { items: cs, more: total - shown };
    } else ccu = sceneRow(nCcu, SCENE.ccu);
    const all = [...bat.items, ...ccu.items];
    const right = Math.max(...all.map((i) => i.x)), xs = right - 8, first = bat.items.filter((q) => q.j === 0).pop() || ccu.items[0];
    return {
      key: `${nCcu}x${nBat}`,
      bat, ccu,
      paths: {
        grid: SCENE.gridWire,
        bat: [[xs, SCENE.wallBase(xs)], [792, SCENE.wallBase(792)], SCENE.houseIn],
        pv: [SCENE.roofIn, [546, 420], [first.x - 4, first.y - SCENE.battery.fy * first.s * 0.92]],
      },
    };
  }
  const pathD = (pts) => "M" + pts.map((q) => `${q[0].toFixed(1)} ${q[1].toFixed(1)}`).join(" L");

  class MaxxichargeCard extends HTMLElement {
    setConfig(config) {
      this._config = { hours: 3, pv_max: 4000, house_max: 3000, ccu_max: 2300, ...config };
      if (this._config.switcher === undefined) this._config.switcher = !this._config.device;
      this._sel = null;
      if (this._config.switcher) {
        try { this._sel = localStorage.getItem(this._selKey()) || null; } catch (e) { this._sel = null; }
      }
      if (!Array.isArray(this._config.modules) || !this._config.modules.length) this._config.modules = ALL_MODULES;
      if (!Array.isArray(this._config.tiles) || !this._config.tiles.length) this._config.tiles = ALL_TILES;
      this._built = false;
      this._hist = null;
      this._histAt = 0;
      if (this._hass) this._render();
    }

    set hass(hass) {
      this._hass = hass;
      if (!this._built) this._render();
      this._update();
      this._maybeLoadHistory();
    }

    getCardSize() {
      return 7;
    }

    static getStubConfig() {
      return {};
    }

    static getConfigElement() {
      return document.createElement("maxxicharge-card-editor");
    }

    disconnectedCallback() {
      this._gone = true;
    }

    // ---------- Daten ----------
    _index() {
      const reg = this._hass.entities || {};
      if (this._regRef === reg && this._idx) return this._idx;
      const byDev = new Map(), byKey = new Map();
      for (const [id, e] of Object.entries(reg)) {
        if (e.platform !== "maxxicharge" || !e.translation_key) continue;
        byDev.set(`${e.device_id}|${e.translation_key}`, id);
        if (!byKey.has(e.translation_key)) byKey.set(e.translation_key, id);
      }
      this._regRef = reg;
      this._idx = { byDev, byKey };
      return this._idx;
    }
    _selKey() {
      return `maxxicharge-card-sel:${this._config.title || ""}:${this._config.device || ""}`;
    }
    _device() {
      if (this._sel) return this._sel === "total" ? undefined : this._sel;
      return this._config.device;
    }
    _devices() {
      const { byDev } = this._index(), ids = new Map();
      for (const key of byDev.keys()) {
        const [id, tk] = key.split("|");
        const d = ids.get(id) || { id, total: false };
        if (tk === "total_soc") d.total = true;
        ids.set(id, d);
      }
      const list = [...ids.values()].map((d) => {
        const dev = (this._hass.devices || {})[d.id] || {};
        return { ...d, name: dev.name_by_user || dev.name || (d.total ? "Gesamt" : "CCU") };
      });
      return list.sort((a, b) => (a.total === b.total ? a.name.localeCompare(b.name) : a.total ? -1 : 1));
    }
    _mode() {
      const dev = this._device();
      if (dev && !this._index().byDev.has(`${dev}|total_soc`)) return "ccu";
      return "total";
    }
    _entity(key) {
      const override = this._config.entities && this._config.entities[key];
      if (override) return override;
      const { byDev, byKey } = this._index();
      if (key === "lock") return byKey.get("write_lock") || null;
      if (this._mode() === "total") return byKey.get(TOTAL_KEYS[key]) || null;
      const tk = CCU_KEYS[key];
      return tk ? byDev.get(`${this._device()}|${tk}`) || null : null;
    }
    _raw(key) {
      const id = this._entity(key);
      const st = id && this._hass.states[id];
      return st ? st.state : null;
    }
    _rawNum(key) {
      const id = this._entity(key);
      const st = id && this._hass.states[id];
      if (!st || st.state === "unknown" || st.state === "unavailable") return null;
      let n = Number(st.state);
      if (Number.isNaN(n)) return null;
      if (key === "pvtoday") {  // Einheit der Entity beachten (CCU: Wh, Gesamt: kWh)
        const unit = st.attributes && st.attributes.unit_of_measurement;
        if (unit === "Wh") n /= 1000;
        else if (unit === "MWh") n *= 1000;
      }
      return n;
    }
    _state(key) {
      if (key === "fault" && this._mode() === "ccu") {
        const on = ["f1", "f2", "f3"].some((k) => this._raw(k) === "on");
        return this._raw("f1") === null ? null : on ? "on" : "off";
      }
      return this._raw(key);
    }
    _num(key) {
      if (this._mode() === "ccu") {
        if (key === "autarky") return null;
        if (key === "house") {  // Verbrauch = Netz + CCU-Abgabe - CCU-Aufnahme (nur mit Zähler an dieser CCU)
          const grid = this._rawNum("grid");
          return grid === null ? null : grid + (this._rawNum("feed") || 0) - (this._rawNum("draw") || 0);
        }
      }
      return this._rawNum(key);
    }
    _title() {
      if (this._config.title) return this._config.title;
      const dev = this._device(), d = dev && this._hass.devices && this._hass.devices[dev];
      return d ? d.name_by_user || d.name || "Maxxicharge" : "Maxxicharge";
    }

    async _maybeLoadHistory() {
      const now = Date.now();
      if (!this._built || this._loading || now - this._histAt < 120000 || !this._hass.callWS) return;
      const idGrid = this._entity("grid"), idFeed = this._entity("feed"), idDraw = this._entity("draw");
      if (!idFeed && !idDraw) return;
      const ids = [idGrid, idFeed, idDraw].filter(Boolean);
      this._loading = true;
      try {
        const hours = Number(this._config.hours) || 3;
        const end = new Date(), start = new Date(end.getTime() - hours * 3600 * 1000);
        const res = await this._hass.callWS({
          type: "history/history_during_period",
          start_time: start.toISOString(),
          end_time: end.toISOString(),
          entity_ids: ids,
          minimal_response: true,
          no_attributes: true,
          significant_changes_only: false,
        });
        const N = 60, t0 = start.getTime() / 1000, dt = (hours * 3600) / N;
        const ser = (id) => {
          if (!id) return null;
          const rows = (res && res[id]) || [];
          const pts = rows
            .map((r) => ({ t: Number(r.lu ?? r.last_updated_ts ?? (r.last_updated ? Date.parse(r.last_updated) / 1000 : NaN)), v: Number(r.s ?? r.state) }))
            .filter((p) => !Number.isNaN(p.t) && !Number.isNaN(p.v));
          let i = 0, last = null;
          const out = [];
          for (let b = 0; b <= N; b++) {
            const tb = t0 + b * dt;
            while (i < pts.length && pts[i].t <= tb) { last = pts[i].v; i++; }
            out.push(last);
          }
          return out;
        };
        const g = ser(idGrid), f = ser(idFeed), d = ser(idDraw);
        const base = f || d;
        this._hist = {
          grid: g || [],
          ccu: base.map((_, i) => {
            const fv = f ? f[i] : null, dv = d ? d[i] : null;
            return fv === null && dv === null ? null : (fv || 0) - (dv || 0);
          }),
        };
        this._histAt = Date.now();
        if (!this._gone) this._drawChart();
      } catch (err) {
        this._histAt = Date.now();
      } finally {
        this._loading = false;
      }
    }

    // ---------- Aufbau ----------
    _render() {
      if (!this.shadowRoot) this.attachShadow({ mode: "open" });
      this.shadowRoot.innerHTML = `
        <style>
          :host { display:block; }
          ha-card { display:block; overflow:hidden; background:linear-gradient(180deg,#0a0e0d 0%,#0b1a12 100%); color:#e8eceb; padding:14px 14px 12px; border-radius:14px; }
          .top { display:flex; align-items:center; justify-content:space-between; min-height:30px; }
          .title { font-weight:600; font-size:1.05em; letter-spacing:.2px; }
          .badges { display:flex; gap:6px; }
          .chips { display:flex; gap:6px; flex-wrap:wrap; margin:6px 0 2px; }
          .chips:empty { display:none; }
          .chip { cursor:pointer; border:1px solid rgba(255,255,255,.2); background:rgba(255,255,255,.04); color:#cfd8d3; border-radius:14px; padding:3px 11px; font:inherit; font-size:.82em; }
          .chip.on { background:#34c759; border-color:#34c759; color:#06210f; font-weight:600; }
          .badge { width:28px; height:28px; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:14px; background:#f2b705; color:#1b1b1b; }
          .badge.lock { background:#d9a21a; }
          .badge.off { background:#555; color:#ddd; }
          .scene { position:relative; margin-top:4px; }
          .scene.flat { display:grid; grid-template-columns:repeat(auto-fit,minmax(118px,1fr)); gap:8px; margin-top:10px; }
          .scene.flat .tile { position:static; width:auto; }
          .scene svg { width:100%; height:auto; display:block; }
          .tile { position:absolute; width:28.5%; min-width:0; overflow:hidden; box-sizing:border-box; background:linear-gradient(160deg,rgba(40,50,55,.92),rgba(20,26,29,.92)); border:1px solid rgba(255,255,255,.14); border-radius:12px; padding:7px 10px 8px; backdrop-filter:blur(4px); box-shadow:0 4px 14px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.06); }
          .tile .k { font-size:10.5px; color:#aeb9bd; display:flex; align-items:center; gap:5px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
          .tile .k .ic { font-size:12px; } .tile .ts { font-size:10px; color:#c4ced1; font-weight:600; min-height:12px; margin-top:1px; white-space:nowrap; }
          .tile .v { font-size:19px; font-weight:700; margin-top:2px; white-space:nowrap; letter-spacing:.2px; }
          .tile .v small { font-size:11px; font-weight:500; color:#aeb9bd; margin-right:4px; }
          .tile .v .u { font-size:12px; font-weight:600; color:#c4ced1; margin-left:2px; }
          .bar { height:4px; border-radius:2px; background:rgba(255,255,255,.12); margin-top:6px; overflow:hidden; }
          .bar i { display:block; height:100%; border-radius:2px; width:0; transition:width .6s; box-shadow:0 0 8px currentColor; }
          .t-pv { left:2%; top:9%; } .t-house { left:69.5%; top:2%; }
          .t-grid { left:2%; bottom:1%; } .t-ccu { left:35.75%; bottom:1%; } .t-store { left:69.5%; bottom:1%; }
          .sect { margin:10px 2px 2px; font-size:.78em; letter-spacing:1.3px; color:#9fb0a8; text-transform:uppercase; display:flex; align-items:center; gap:6px; }
          #chart { width:100%; height:auto; display:block; }
          .ax { font-size:9.5px; fill:#8da097; }
          .pulse { transform-box:fill-box; transform-origin:center; animation:pulse 2.4s ease-out infinite; }
          @keyframes pulse { 0% { transform:scale(1); opacity:.8; } 100% { transform:scale(3.2); opacity:0; } }
          @media (prefers-reduced-motion: reduce) { .pulse { animation:none; opacity:0; } }
          .legend { display:grid; grid-template-columns:1fr auto 1fr; align-items:center; gap:6px; font-size:.78em; margin-top:2px; }
          .legend .col { display:flex; flex-direction:column; gap:3px; color:#b9c4c0; }
          .legend .col.r { align-items:flex-end; text-align:right; }
          .legend .dot { display:inline-block; width:8px; height:8px; border-radius:50%; margin-right:5px; }
          .legend .r .dot { margin:0 0 0 5px; }
          .nums { display:flex; gap:18px; }
          .num { text-align:center; }
          .num .n { font-family:"Roboto Condensed","Arial Narrow",Roboto,sans-serif; font-size:2em; font-weight:700; line-height:1.05; }
          .num .cap { font-size:.78em; color:#9fb0a8; margin-top:1px; }
          .foot { display:grid; grid-template-columns:repeat(auto-fit,minmax(104px,1fr)); gap:8px; margin-top:12px; }
          .st { background:rgba(255,255,255,.05); border:1px solid rgba(255,255,255,.07); border-radius:10px; padding:7px 10px; }
          .st .sl { font-size:.72em; color:#9fb0a8; letter-spacing:.3px; } .st .sv { font-size:1.02em; font-weight:600; color:#eef2f1; margin-top:1px; }
          .msg { padding:18px 8px; color:#9fb0a8; }
          .flowdot { display:none; filter:drop-shadow(0 0 3px rgba(255,255,255,.7)); }
          .node { fill:#3ecf5a; stroke:rgba(255,255,255,.55); stroke-width:.8; filter:drop-shadow(0 0 2.5px rgba(62,207,90,.8)); }
          .flowglow, .flowrun { display:none; }
          .on .flowglow { display:inline; opacity:.35; }
          .on .flowrun { display:inline; stroke-dasharray:1 11; animation:flowmove var(--fd,1.6s) linear infinite; }
          .on .flowrun.rev { animation-direction:reverse; }
          @keyframes flowmove { to { stroke-dashoffset:-12; } }
          @media (prefers-reduced-motion: reduce) { .on .flowrun { animation:none; } }
          .on .flowdot { display:inline; }
        </style>
        <ha-card>
          <div class="top"><div class="title"></div><div class="badges" id="badges"></div></div>
          <div class="chips" id="chips"></div>
          <div class="msg" id="msg" hidden>Keine Maxxicharge-Werte gefunden. Wähle im Karten-Editor ein Gerät aus oder richte „Maxxicharge Gesamt“ ein.</div>
          <div id="main">
            <div class="scene" id="scene">
              ${this._houseSvg()}
              <div class="tile t-pv" data-tile="pv"><div class="k"><span class="ic">☀️</span>PV-Leistung</div><div class="v" id="v-pv">–</div><div class="bar"><i id="b-pv" style="background:linear-gradient(90deg,#f5a623,#ff7a18);color:#ff9a2e"></i></div></div>
              <div class="tile t-house" data-tile="house"><div class="k"><span class="ic">🏠</span>Verbrauch</div><div class="v" id="v-house">–</div><div class="bar"><i id="b-house" style="background:${C.green};color:${C.green}"></i></div></div>
              <div class="tile t-grid" data-tile="grid"><div class="k"><span class="ic">⚡</span>Netz</div><div class="v" id="v-grid">–</div><div class="ts" id="s-grid"></div><div class="bar"><i id="b-grid" style="background:${C.blue};color:${C.blue}"></i></div></div>
              <div class="tile t-ccu" data-tile="ccu"><div class="k"><span class="ic">🔌</span>CCU-Abgabe</div><div class="v" id="v-ccu">–</div><div class="bar"><i id="b-ccu" style="background:${C.ccu};color:${C.ccu}"></i></div></div>
              <div class="tile t-store" data-tile="store"><div class="k"><span class="ic">🔋</span>Speicher</div><div class="v" id="v-soc">–</div><div class="ts" id="s-state"></div><div class="bar"><i id="b-soc" style="background:${C.green};color:${C.green}"></i></div></div>
            </div>
            <div id="m-chart">
            <div class="sect">⚡ Haushalt</div>
            ${this._chartSvg()}
            <div class="legend">
              <div class="col"><span><span class="dot" style="background:${C.grid}"></span>Netzbezug</span><span><span class="dot" style="background:#7a3050"></span>Einspeisung</span></div>
              <div class="nums"><div class="num"><div class="n" id="n-grid" style="color:${C.grid}">–</div><div class="cap" id="c-grid">Netzbezug</div></div><div class="num"><div class="n" id="n-ccu" style="color:${C.ccu}">–</div><div class="cap" id="c-ccu">CCU-Abgabe</div></div></div>
              <div class="col r"><span>CCU-Abgabe<span class="dot" style="background:${C.ccu}"></span></span><span>CCU-Aufnahme<span class="dot" style="background:#6d58a8"></span></span></div>
            </div>
            </div>
            <div class="foot" id="foot"></div>
          </div>
        </ha-card>`;
      this._built = true;
      this._applyLayout();
    }

    _renderChips() {
      const box = this.shadowRoot.getElementById("chips");
      if (!this._config.switcher) { box.innerHTML = ""; return; }
      const devs = this._devices();
      const current = this._sel || (this._config.device ? this._config.device : "total");
      const sig = `${current}|${devs.map((d) => d.id + d.name).join(",")}`;
      if (sig === this._chipSig) return;
      this._chipSig = sig;
      box.innerHTML = "";
      if (devs.length < 2) return;
      for (const d of devs) {
        const key = d.total ? "total" : d.id;
        const b = document.createElement("button");
        b.className = `chip${current === key || (d.total && current === "total") ? " on" : ""}`;
        b.textContent = d.name;
        b.onclick = () => this._select(key);
        box.appendChild(b);
      }
    }

    _select(key) {
      this._sel = key;
      try { localStorage.setItem(this._selKey(), key); } catch (e) { /* ohne Speicher weiter */ }
      this._hist = null;
      this._histAt = 0;
      this._chipSig = "";
      this._update();
      this._maybeLoadHistory();
    }

    _applyLayout() {
      const $ = (id) => this.shadowRoot.getElementById(id);
      const mods = new Set(this._config.modules), tiles = new Set(this._config.tiles);
      const art = mods.has("scene"), showTiles = mods.has("tiles");
      $("scene").style.display = art || showTiles ? "" : "none";
      $("scene").classList.toggle("flat", !art);
      $("house").style.display = art ? "" : "none";
      this.shadowRoot.querySelectorAll("[data-tile]").forEach((el) => {
        el.style.display = showTiles && tiles.has(el.dataset.tile) ? "" : "none";
      });
      this.shadowRoot.querySelectorAll("[data-t]").forEach((el) => {
        el.style.display = showTiles && tiles.has(el.dataset.t) ? "" : "none";
      });
      $("m-chart").style.display = mods.has("chart") ? "" : "none";
      $("foot").style.display = mods.has("stats") ? "" : "none";
    }

    // Anzahl der CCUs und Speicher: aus der Konfiguration (ccus, storages) oder aus den Geräten in Home Assistant.
    _counts() {
      let nC = Number(this._config.ccus) || 0, nB = Number(this._config.storages) || 0;
      if (!nC || !nB) {
        const { byDev } = this._index();
        const ids = this._mode() === "ccu" ? [this._device()] : this._devices().filter((d) => !d.total).map((d) => d.id);
        if (!nC) nC = Math.max(1, ids.length);
        if (!nB) {
          let sum = 0;
          for (const id of ids) {
            const eid = byDev.get(`${id}|battery_count`), st = eid && this._hass && this._hass.states[eid], v = st ? Number(st.state) : NaN;
            sum += Number.isFinite(v) && v > 0 ? v : 1;
          }
          nB = Math.max(1, sum);
        }
      }
      return [Math.min(nC, 12), Math.min(nB, 24)];
    }

    // Szene neu aufbauen, wenn sich die Anzahl der Geräte ändert.
    _syncScene() {
      if (!this._built || !this._hass) return;
      const [nC, nB] = this._counts(), key = `${nC}x${nB}`;
      if (key === this._sceneKey) return;
      this._sceneKey = key;
      this.shadowRoot.getElementById("house").innerHTML = this._sceneInner(sceneLayout(nC, nB));
      this._applyLayout();
      this._update();
    }

    _houseSvg() {
      this._sceneKey = "1x1";
      return `<svg viewBox="0 0 400 316" id="house" role="img" aria-label="Haus mit Zähler, CCU und Speicher">${this._sceneInner(sceneLayout(1, 1))}</svg>`;
    }

    _sceneInner(lay) {
      const k = SCENE_K, P = (q) => `${(q[0] * k).toFixed(1)},${(q[1] * k).toFixed(1)}`;
      // Solarmodule auf der Dachfläche: zwei Reihen mit je sechs Modulen
      const QA = [437, 38], QB = [738, 100], QC = [527, 362], QD = [258, 236];
      const Q = (u, v) => [
        QA[0] * (1 - u) * (1 - v) + QB[0] * u * (1 - v) + QC[0] * u * v + QD[0] * (1 - u) * v,
        QA[1] * (1 - u) * (1 - v) + QB[1] * u * (1 - v) + QC[1] * u * v + QD[1] * (1 - u) * v,
      ];
      let panels = "";
      const pc = 6, pr = 2, pmu = 0.07, pmv = 0.12, pgu = 0.018, pgv = 0.05;
      const pw = (1 - 2 * pmu - (pc - 1) * pgu) / pc, ph = (1 - 2 * pmv - (pr - 1) * pgv) / pr;
      for (let r = 0; r < pr; r++) for (let c = 0; c < pc; c++) {
        const u0 = pmu + c * (pw + pgu), v0 = pmv + r * (ph + pgv);
        panels += `<polygon points="${[Q(u0, v0), Q(u0 + pw, v0), Q(u0 + pw, v0 + ph), Q(u0, v0 + ph)].map((m) => m.map((n) => n.toFixed(1)).join(",")).join(" ")}" fill="#1b232a" stroke="#556169" stroke-width="2"/>`;
      }
      // Leitung: heller Draht, darüber die farbige Leitung (nur bei Stromfluss) und der wandernde Punkt
      const wire = (id, pts, color) => `
            <path d="${pathD(pts)}" fill="none" stroke="#e8eef1" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round" opacity=".85"/>
            <path id="p-${id}" d="${pathD(pts)}" fill="none" stroke="${color}" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round" opacity="0"/>
            <circle class="flowdot" id="d-${id}" r="8" fill="${color}"/>`;
      const node = (q) => `<circle class="node" cx="${q[0].toFixed(1)}" cy="${q[1].toFixed(1)}" r="6"/>`;
      // Geräte: Speicher als Sprite aus dem Render, CCU als Produktfoto (an der Hauswand ausgerichtet)
      const B = SCENE.battery, Cc = SCENE.ccu;
      const shadow = (it, rx) => `<ellipse cx="${it.x.toFixed(1)}" cy="${(it.y + 4).toFixed(1)}" rx="${(rx * it.s).toFixed(1)}" ry="${(rx * 0.24 * it.s).toFixed(1)}" fill="#55616a" opacity=".3"/>`;
      const sprite = (img, S, it) => `<image href="${img}" x="${(it.x - S.fx * it.s).toFixed(1)}" y="${(it.y - S.fy * it.s).toFixed(1)}" width="${(S.w * it.s).toFixed(1)}" height="${(S.h * it.s).toFixed(1)}"/>`;
      let devs = "";
      // von hinten nach vorn Turm für Turm: Speicher von unten nach oben, dann die CCU(s) obendrauf
      const nTow = Math.max(-1, ...lay.bat.items.map((q) => q.j)) + 1;
      for (let j = nTow - 1; j >= 0; j--) {
        for (const b of lay.bat.items.filter((q) => q.j === j)) devs += (b.l === 0 ? shadow(b, 40) : "") + sprite(SCENE_IMG.battery, B, b);
        for (const c of lay.ccu.items.filter((q) => q.j === j)) devs += sprite(SCENE_IMG.ccu, Cc, c);
      }
      for (const it of lay.ccu.items.filter((q) => q.j === undefined).reverse()) devs += shadow(it, 38) + sprite(SCENE_IMG.ccu, Cc, it);
      const lastB = lay.bat.items[lay.bat.items.length - 1];
      if (lay.bat.more && lastB) devs += `<text x="${(lastB.x + 40).toFixed(1)}" y="${(lastB.y - 40).toFixed(1)}" font-size="26" font-weight="700" fill="#cfdbe1" font-family="sans-serif">+${lay.bat.more}</text>`;
      const lastC = lay.ccu.items[lay.ccu.items.length - 1];
      if (lay.ccu.more && lastC) devs += `<text x="${(lastC.x + 30).toFixed(1)}" y="${(lastC.y + 4).toFixed(1)}" font-size="22" font-weight="700" fill="#cfdbe1" font-family="sans-serif">+${lay.ccu.more}</text>`;
      // Leitlinien der Kacheln zu den Teilen der Szene (Koordinaten der viewBox)
      const lead = (id, from, to) => `<g data-t="${id}"><path d="M${from[0]} ${from[1]} L${to[0].toFixed(1)} ${to[1].toFixed(1)}" stroke="rgba(255,255,255,.32)" stroke-width="1" stroke-dasharray="2 3" fill="none"/><circle cx="${to[0].toFixed(1)}" cy="${to[1].toFixed(1)}" r="2" fill="rgba(255,255,255,.7)"/></g>`;
      const fb = lay.bat.items[0], fc = lay.ccu.items[0];
      const leaders = lead("pv", [116, 56], [206, 82]) + lead("grid", [60, 254], [103, 224])
        + lead("ccu", [262, 254], [fc.x * k, (fc.y - 10) * k]) + lead("store", [330, 254], [fb.x * k, (fb.y - 40) * k]);
      return `
          <defs>
            <radialGradient id="hmg" cx=".5" cy=".46" r=".58"><stop offset=".62" stop-color="#fff"/><stop offset="1" stop-color="#000"/></radialGradient>
            <mask id="hm"><rect width="400" height="292.4" fill="url(#hmg)"/></mask>
            <radialGradient id="gGlow"><stop offset="0" stop-color="#ffb347" stop-opacity=".55"/><stop offset="1" stop-color="#ffb347" stop-opacity="0"/></radialGradient>
            <radialGradient id="gSun"><stop offset="0" stop-color="#fff2b0" stop-opacity=".9"/><stop offset="1" stop-color="#ffd24d" stop-opacity="0"/></radialGradient>
          </defs>
          <image href="${SCENE_IMG.house}" x="0" y="0" width="400" height="292.4" mask="url(#hm)"/>
          <g transform="scale(${k})" id="panels">${panels}</g>
          <ellipse id="glow" cx="300" cy="112" rx="62" ry="48" fill="url(#gGlow)" opacity="0"/>
          <ellipse id="sun" cx="208" cy="74" rx="70" ry="34" fill="url(#gSun)" opacity="0"/>
          <polygon id="win" points="258,103 290,62 340,106 339,133 289,147 257,156" fill="#0b130e" opacity="0"/>
          ${leaders}
          <g transform="scale(${k})">
            ${wire("grid", lay.paths.grid, C.blue)}
            ${wire("bat", lay.paths.bat, C.green)}
            <g id="devices">${devs}</g>
            ${wire("pv", lay.paths.pv, C.pv)}
            ${node([792, SCENE.wallBase(792)])}${node(SCENE.roofIn)}
          </g>`;
    }

    _chartSvg() {
      return `<svg id="chart" viewBox="0 0 400 128" role="img" aria-label="Verlauf Haushalt">
        <defs>
          <linearGradient id="gr-grid" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${C.grid}" stop-opacity=".38"/><stop offset="1" stop-color="${C.grid}" stop-opacity="0"/></linearGradient>
          <linearGradient id="gr-ccu" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${C.ccu}" stop-opacity=".30"/><stop offset="1" stop-color="${C.ccu}" stop-opacity="0"/></linearGradient>
          <clipPath id="cp-pos"><rect id="cp-pos-r" x="0" y="0" width="400" height="0"/></clipPath>
          <clipPath id="cp-neg"><rect id="cp-neg-r" x="0" y="0" width="400" height="0"/></clipPath>
        </defs>
        <filter id="cblur" x="-5%" y="-30%" width="110%" height="160%"><feGaussianBlur stdDeviation="2.2"/></filter>
        <g id="grid-lines"></g>
        <path id="area-ccu" fill="url(#gr-ccu)" clip-path="url(#cp-pos)"/>
        <path id="area-grid" fill="url(#gr-grid)" clip-path="url(#cp-pos)"/>
        <path id="area-grid-n" fill="${C.grid}" opacity=".14" clip-path="url(#cp-neg)"/>
        <path id="gl-ccu" fill="none" stroke="${C.ccu}" stroke-width="5" opacity=".28" filter="url(#cblur)" stroke-linejoin="round" stroke-linecap="round"/>
        <path id="gl-grid" fill="none" stroke="${C.grid}" stroke-width="5" opacity=".28" filter="url(#cblur)" stroke-linejoin="round" stroke-linecap="round"/>
        <path id="ln-ccu" fill="none" stroke="${C.ccu}" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>
        <path id="ln-grid" fill="none" stroke="${C.grid}" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>
        <circle id="pu-grid" r="3" fill="none" stroke="${C.grid}" display="none" class="pulse"/>
        <circle id="pu-ccu" r="3" fill="none" stroke="${C.ccu}" display="none" class="pulse"/>
        <circle id="dot-grid" r="3.2" fill="${C.grid}" stroke="#0d1511" stroke-width="1.2" display="none"/>
        <circle id="dot-ccu" r="3.2" fill="${C.ccu}" stroke="#0d1511" stroke-width="1.2" display="none"/>
        <g id="hv" display="none" pointer-events="none">
          <line id="hv-l" y1="8" y2="106" stroke="rgba(255,255,255,.35)" stroke-dasharray="2 3"/>
          <circle id="hv-g" r="3.2" fill="${C.grid}" stroke="#0d1511" stroke-width="1"/>
          <circle id="hv-c" r="3.2" fill="${C.ccu}" stroke="#0d1511" stroke-width="1"/>
          <g id="hv-box"><rect id="hv-bg" rx="5" fill="rgba(10,16,13,.92)" stroke="rgba(255,255,255,.14)"/><text id="hv-t0" class="ax" fill="#b9c4c0"></text><text id="hv-t1" class="ax" fill="${C.grid}"></text><text id="hv-t2" class="ax" fill="${C.ccu}"></text></g>
        </g>
        <rect id="hv-hit" x="0" y="0" width="400" height="128" fill="transparent"/>
        <text class="ax" id="t-none" x="200" y="62" text-anchor="middle"></text>
      </svg>`;
    }

    // ---------- Anzeige ----------
    _setDot(id, pathId, watts, forward, color) {
      const dot = this.shadowRoot.getElementById(id), path = this.shadowRoot.getElementById(pathId);
      const on = watts !== null && Math.abs(watts) >= 10;
      dot.style.display = on ? "inline" : "none";
      // dünne Linie; bei Fluss in der Farbe der Quelle, sonst hell und ruhig
      path.setAttribute("stroke", color);
      path.setAttribute("opacity", on ? ".95" : "0");
      if (!on) { dot.innerHTML = ""; dot.dataset.key = ""; return; }
      const w = Math.min(Math.abs(watts), 2300);
      const key = `${forward}|${Math.round(w / 400)}`;
      if (dot.dataset.key === key) return;
      dot.dataset.key = key;
      const mv = Math.max(1.4, 4.2 - w / 800);
      dot.setAttribute("r", "8");
      dot.innerHTML = `<animateMotion dur="${mv}s" repeatCount="indefinite" keyPoints="${forward ? "0;1" : "1;0"}" keyTimes="0;1" calcMode="linear"><mpath href="#${pathId}"/></animateMotion>`;
    }

    _update() {
      if (!this._built || !this._hass) return;
      this._syncScene();
      const $ = (id) => this.shadowRoot.getElementById(id);
      const pv = this._num("pv"), grid = this._num("grid"), house = this._num("house"), soc = this._num("soc");
      const ch = this._num("charge"), dis = this._num("discharge"), feed = this._num("feed"), draw = this._num("draw");
      this.shadowRoot.querySelector(".title").textContent = this._title();
      this._renderChips();
      const ok = [pv, grid, house, soc].some((v) => v !== null);
      $("msg").hidden = ok;
      $("main").style.display = ok ? "" : "none";

      $("b-pv").style.width = `${pct(pv, this._config.pv_max)}%`;
      $("b-house").style.width = `${pct(house, this._config.house_max)}%`;
      const ccu = feed === null && draw === null ? null : (feed || 0) - (draw || 0);
      const t = this._num("temp");
      const split = (txt) => (txt === "–" ? txt : txt.replace(/ (W|kW)$/, '<span class="u">$1</span>'));
      $("v-pv").innerHTML = split(fmtW(pv));
      $("v-house").innerHTML = split(fmtW(house));
      $("v-grid").innerHTML = split(fmtW(grid === null ? null : Math.abs(grid)));
      $("b-grid").style.width = `${pct(grid === null ? null : Math.abs(grid), this._config.house_max)}%`;
      $("s-grid").textContent = grid === null || Math.abs(grid) < 10 ? "" : grid > 0 ? "Bezug" : "Einspeisung";
      $("v-ccu").innerHTML = `${t !== null ? `<small>${Math.round(t)} °C ·</small>` : ""}${split(fmtW(ccu === null ? null : Math.max(ccu, 0)))}`;
      $("b-ccu").style.width = `${pct(ccu === null ? null : Math.max(ccu, 0), this._config.ccu_max)}%`;
      $("v-soc").textContent = soc === null ? "–" : `${Math.round(soc)} %`;
      $("b-soc").style.width = `${pct(soc, 100)}%`;
      $("s-state").textContent = (dis || 0) > 10 ? `↓ ${fmtW(dis)}` : (ch || 0) > 10 ? `↑ ${fmtW(ch)}` : "";

      // Haus: Fenster leuchtet bei Verbrauch, Speicher-LEDs zeigen Laden/Entladen
      const lit = house !== null && house > 30 ? Math.min(1, 0.45 + house / 3000) : 0.18;
      $("win").setAttribute("opacity", (0.6 * (1 - lit)).toFixed(2));
      $("glow").setAttribute("opacity", house !== null && house > 30 ? Math.min(0.9, lit) : 0);
      $("sun").setAttribute("opacity", pv !== null && pv > 20 ? Math.min(0.85, 0.25 + pv / 4000) : 0);

      // Leitungen mit wandernden Punkten: PV -> Speicher, Speicher <-> Haus, Netz <-> Haus
      // Leitungen wie im Hausbild: Netz↔CCU (Zähler zum Speicher), CCU→Haus, Solar→CCU
      this._setDot("d-pv", "p-pv", pv, true, C.pv);
      this._setDot("d-grid", "p-grid", grid, (grid || 0) >= 0, C.blue);
      this._setDot("d-bat", "p-bat", feed === null && draw === null ? null : feed || 0, true, C.green);

      $("n-grid").textContent = fmtW(grid === null ? null : Math.abs(grid));
      $("n-ccu").textContent = fmtW(ccu === null ? null : Math.abs(ccu));
      $("c-grid").textContent = grid !== null && grid < 0 ? "Einspeisung" : "Netzbezug";
      $("c-ccu").textContent = ccu !== null && ccu < 0 ? "CCU-Aufnahme" : "CCU-Abgabe";

      const usable = this._num("usable"), runtime = this._num("runtime"), ttf = this._num("ttf");
      const autarky = this._num("autarky"), pvToday = this._num("pvtoday");
      const parts = [];
      const stat = (label, value) => `<div class="st"><div class="sl">${label}</div><div class="sv">${value}</div></div>`;
      if (pvToday !== null) parts.push(stat("PV heute", `${pvToday.toFixed(1).replace(".", ",")} kWh`));
      if (autarky !== null) parts.push(stat("Autarkie heute", `${Math.round(autarky)} %`));
      if (runtime !== null) parts.push(stat("Reicht noch", fmtH(runtime)));
      else if (ttf !== null) parts.push(stat("Voll in", fmtH(ttf)));
      if (usable !== null) parts.push(stat("Nutzbar", `${usable.toFixed(2).replace(".", ",")} kWh`));
      $("foot").innerHTML = parts.join("");

      const badges = [];
      if (this._state("online") === "off") badges.push(`<div class="badge off" title="CCU offline">☁</div>`);
      if (this._state("fault") === "on") badges.push(`<div class="badge" title="Störung">!</div>`);
      if (this._state("lock") === "on") badges.push(`<div class="badge lock" title="Schreibschutz">🔒</div>`);
      $("badges").innerHTML = badges.join("");
      this._drawChart();
    }

    _drawChart() {
      const $ = (id) => this.shadowRoot.getElementById(id);
      const none = $("t-none");
      if (!this._hist) { none.textContent = this._hass && this._hass.callWS ? "Verlauf wird geladen …" : ""; return; }
      none.textContent = "";
      const L = 38, R = 392, T = 8, B = 106, W = R - L, N = Math.max(this._hist.grid.length, this._hist.ccu.length) - 1;
      const gv = this._hist.grid.filter((v) => v !== null), cv = this._hist.ccu.filter((v) => v !== null);
      if (!gv.length && !cv.length) { none.textContent = "Keine Verlaufsdaten"; return; }
      // eine gemeinsame Achse für beide Linien: gleiche Skala, Null liegt auf einer Linie
      const r = niceRange([...gv, ...cv]);
      const y = (v) => T + (1 - (v - r.lo) / (r.hi - r.lo)) * (B - T);
      const x = (i) => L + (i / N) * W;
      const y0 = y(0);
      const fmtAx = (v) => (Math.abs(v) >= 1000 ? `${String(v / 1000).replace(".", ",")} kW` : `${v} W`);
      // Linie ohne Überschwinger (monotone kubische Kurve), Lücken bei fehlenden Werten
      const segs = (arr) => {
        const out = []; let cur = [];
        arr.forEach((v, i) => { if (v === null) { if (cur.length) out.push(cur); cur = []; } else cur.push([x(i), y(v)]); });
        if (cur.length) out.push(cur);
        return out;
      };
      const curve = (pts) => {
        const n = pts.length;
        if (n === 1) return `M${pts[0][0].toFixed(1)},${pts[0][1].toFixed(1)}`;
        const dx = [], m = [], t = new Array(n).fill(0);
        for (let k = 0; k < n - 1; k++) { dx[k] = pts[k + 1][0] - pts[k][0]; m[k] = (pts[k + 1][1] - pts[k][1]) / dx[k]; }
        t[0] = m[0]; t[n - 1] = m[n - 2];
        for (let k = 1; k < n - 1; k++) t[k] = m[k - 1] * m[k] <= 0 ? 0 : (m[k - 1] + m[k]) / 2;
        for (let k = 0; k < n - 1; k++) {
          if (m[k] === 0) { t[k] = 0; t[k + 1] = 0; continue; }
          const a = t[k] / m[k], b = t[k + 1] / m[k], h = a * a + b * b;
          if (h > 9) { const s3 = 3 / Math.sqrt(h); t[k] = s3 * a * m[k]; t[k + 1] = s3 * b * m[k]; }
        }
        let d = `M${pts[0][0].toFixed(1)},${pts[0][1].toFixed(1)}`;
        for (let k = 0; k < n - 1; k++) {
          const h = dx[k] / 3;
          d += ` C${(pts[k][0] + h).toFixed(1)},${(pts[k][1] + t[k] * h).toFixed(1)} ${(pts[k + 1][0] - h).toFixed(1)},${(pts[k + 1][1] - t[k + 1] * h).toFixed(1)} ${pts[k + 1][0].toFixed(1)},${pts[k + 1][1].toFixed(1)}`;
        }
        return d;
      };
      const line = (arr) => segs(arr).map(curve).join(" ");
      const area = (arr) => segs(arr).map((p) => `${curve(p)} L${p[p.length - 1][0].toFixed(1)},${y0.toFixed(1)} L${p[0][0].toFixed(1)},${y0.toFixed(1)} Z`).join(" ");
      let grid = "";
      for (let k = 0; k <= 4; k++) {
        const v = r.hi - k * r.step, yy = y(v);
        grid += `<line x1="${L}" x2="${R}" y1="${yy}" y2="${yy}" stroke="rgba(255,255,255,${v === 0 ? ".22" : ".07"})"${v === 0 ? "" : ' stroke-dasharray="1 3"'}/>`;
        grid += `<text class="ax" x="${L - 5}" y="${yy + 3}" text-anchor="end">${fmtAx(v)}</text>`;
      }
      const hours = Number(this._config.hours) || 3;
      const tt = (k, n) => { const d = new Date(Date.now() - (hours * 3600 * 1000) * (1 - k / n)); return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`; };
      for (let k = 0; k <= 3; k++) grid += `<text class="ax" x="${L + (k / 3) * W}" y="${B + 15}" text-anchor="${k === 0 ? "start" : k === 3 ? "end" : "middle"}">${tt(k, 3)}</text>`;
      $("grid-lines").innerHTML = grid;
      // Flächen: oberhalb der Nulllinie farbig verlaufend, darunter (Einspeisung/Aufnahme) dezent
      $("cp-pos-r").setAttribute("y", T); $("cp-pos-r").setAttribute("height", Math.max(0, y0 - T));
      $("cp-neg-r").setAttribute("y", y0); $("cp-neg-r").setAttribute("height", Math.max(0, B - y0));
      $("area-grid").setAttribute("d", area(this._hist.grid));
      $("area-grid-n").setAttribute("d", area(this._hist.grid));
      $("area-ccu").setAttribute("d", area(this._hist.ccu));
      $("ln-grid").setAttribute("d", line(this._hist.grid));
      $("ln-ccu").setAttribute("d", line(this._hist.ccu));
      $("gl-grid").setAttribute("d", line(this._hist.grid));
      $("gl-ccu").setAttribute("d", line(this._hist.ccu));
      const endDot = (id, pid, arr) => {
        let i = arr.length - 1;
        while (i >= 0 && arr[i] === null) i--;
        const el = $(id), pu = $(pid);
        if (i < 0) { el.setAttribute("display", "none"); pu.setAttribute("display", "none"); return; }
        for (const e of [el, pu]) { e.setAttribute("display", ""); e.setAttribute("cx", x(i)); e.setAttribute("cy", y(arr[i])); }
      };
      endDot("dot-grid", "pu-grid", this._hist.grid);
      endDot("dot-ccu", "pu-ccu", this._hist.ccu);
      // Fadenkreuz mit Werten beim Darüberfahren / Antippen
      const hit = $("hv-hit"), hv = $("hv"), svg = $("chart");
      const fW = (v) => (v === null || v === undefined ? "–" : `${Math.round(v)} W`);
      const move = (ev) => {
        const b = svg.getBoundingClientRect();
        const px = ((ev.clientX - b.left) / b.width) * 400;
        const i = Math.max(0, Math.min(N, Math.round(((px - L) / W) * N)));
        const g = this._hist.grid[i], c = this._hist.ccu[i];
        hv.setAttribute("display", "");
        $("hv-l").setAttribute("x1", x(i)); $("hv-l").setAttribute("x2", x(i));
        const dot = (id, v) => { const e = $(id); if (v === null || v === undefined) e.setAttribute("display", "none"); else { e.setAttribute("display", ""); e.setAttribute("cx", x(i)); e.setAttribute("cy", y(v)); } };
        dot("hv-g", g); dot("hv-c", c);
        const hrs = tt(i, N), gl = g === null || g === undefined ? "Netz –" : `${g >= 0 ? "Bezug" : "Einspeisung"} ${fW(Math.abs(g))}`;
        const cl = c === null || c === undefined ? "CCU –" : `${c >= 0 ? "CCU-Abgabe" : "CCU-Aufnahme"} ${fW(Math.abs(c))}`;
        $("hv-t0").textContent = hrs; $("hv-t1").textContent = gl; $("hv-t2").textContent = cl;
        const bw = 112, bh = 40, bx = x(i) > L + W / 2 ? x(i) - bw - 8 : x(i) + 8, by = T + 2;
        $("hv-bg").setAttribute("x", bx); $("hv-bg").setAttribute("y", by); $("hv-bg").setAttribute("width", bw); $("hv-bg").setAttribute("height", bh);
        [["hv-t0", 11], ["hv-t1", 22], ["hv-t2", 33]].forEach(([id, dy]) => { $(id).setAttribute("x", bx + 7); $(id).setAttribute("y", by + dy); });
      };
      hit.onpointermove = move; hit.onpointerdown = move;
      hit.onpointerleave = () => hv.setAttribute("display", "none");
    }
  }

  // ---------- Karten-Editor (Gerät und Bausteine auswählen) ----------
  const LABELS = {
    title: "Titel (leer = Gerätename)",
    device: "Startgerät (leer = Maxxicharge Gesamt)",
    switcher: "Umschalter zwischen Geräten in der Karte anzeigen",
    modules: "Bausteine",
    tiles: "Kacheln",
    hours: "Verlauf in Stunden",
    pv_max: "PV-Balken Maximum (W)",
    house_max: "Verbrauchs-Balken Maximum (W)",
    ccu_max: "CCU-Balken Maximum (W)",
  };
  const SCHEMA = [
    { name: "device", selector: { device: { filter: [{ integration: "maxxicharge" }] } } },
    { name: "switcher", selector: { boolean: {} } },
    { name: "title", selector: { text: {} } },
    {
      name: "modules",
      selector: {
        select: {
          multiple: true,
          mode: "list",
          options: [
            { value: "scene", label: "Haus-Grafik" },
            { value: "tiles", label: "Kacheln" },
            { value: "chart", label: "Verlauf „Haushalt“" },
            { value: "stats", label: "Kennzahlen" },
          ],
        },
      },
    },
    {
      name: "tiles",
      selector: {
        select: {
          multiple: true,
          mode: "list",
          options: [
            { value: "pv", label: "PV-Leistung" },
            { value: "house", label: "Verbrauch" },
            { value: "grid", label: "Netz" },
            { value: "ccu", label: "CCU-Abgabe" },
            { value: "store", label: "Speicher" },
          ],
        },
      },
    },
    { name: "hours", selector: { number: { min: 1, max: 24, mode: "box" } } },
    {
      type: "grid",
      name: "",
      schema: [
        { name: "pv_max", selector: { number: { min: 500, max: 20000, step: 100, mode: "box" } } },
        { name: "house_max", selector: { number: { min: 500, max: 20000, step: 100, mode: "box" } } },
        { name: "ccu_max", selector: { number: { min: 500, max: 5000, step: 100, mode: "box" } } },
      ],
    },
  ];

  class MaxxichargeCardEditor extends HTMLElement {
    setConfig(config) {
      this._config = config;
      this._draw();
    }

    set hass(hass) {
      this._hass = hass;
      if (this._form) this._form.hass = hass;
    }

    _draw() {
      if (!this._form) {
        this._form = document.createElement("ha-form");
        this._form.computeLabel = (item) => LABELS[item.name] || item.name;
        this._form.addEventListener("value-changed", (ev) => {
          ev.stopPropagation();
          const value = { ...ev.detail.value, type: "custom:maxxicharge-card" };
          Object.keys(value).forEach((k) => (value[k] === "" || value[k] === undefined) && delete value[k]);
          this.dispatchEvent(new CustomEvent("config-changed", { detail: { config: value }, bubbles: true, composed: true }));
        });
        this.appendChild(this._form);
      }
      this._form.hass = this._hass;
      this._form.schema = SCHEMA;
      this._form.data = {
        switcher: !this._config.device,
        modules: ALL_MODULES,
        tiles: ALL_TILES,
        hours: 3,
        pv_max: 4000,
        house_max: 3000,
        ccu_max: 2300,
        ...this._config,
      };
    }
  }

  if (!customElements.get("maxxicharge-card")) customElements.define("maxxicharge-card", MaxxichargeCard);
  if (!customElements.get("maxxicharge-card-editor")) customElements.define("maxxicharge-card-editor", MaxxichargeCardEditor);
  window.customCards = window.customCards || [];
  window.customCards.push({
    type: "maxxicharge-card",
    name: "Maxxicharge",
    description: "Haus mit PV und Speicher, Kacheln und Verlauf im Stil der Maxxisun-App, für die Gesamtübersicht oder eine einzelne CCU, modular einstellbar.",
  });
})();
